const lots=[
{name:'Night Runner',type:'VEHICLE / STREET',rarity:'RARE',power:78,price:4200,traits:['⚡ SPEED','◈ STEALTH'],plate:'NIGHT<br>RUNNER',color:'#46a0b1'},
{name:'Cobalt Marquis',type:'PROPERTY / HIDEOUT',rarity:'EPIC',power:91,price:6800,traits:['◆ PRIVACY','⌂ STORAGE'],plate:'COBALT<br>MARQUIS',color:'#b44e87'},
{name:'Golden Viper',type:'VEHICLE / EXOTIC',rarity:'LEGENDARY',power:96,price:9200,traits:['⚡ SPEED','★ STATUS'],plate:'GOLDEN<br>VIPER',color:'#d1a84a'},
{name:'Saltwire Boat',type:'VESSEL / COASTAL',rarity:'RARE',power:72,price:3700,traits:['≋ ESCAPE','◈ STEALTH'],plate:'SALT<br>WIRE',color:'#50a8a1'},
{name:'Neon Palazzo',type:'PROPERTY / CLUB',rarity:'EPIC',power:88,price:7500,traits:['◆ INCOME','★ STATUS'],plate:'NEON<br>PALAZZO',color:'#dc5f71'},
{name:'Overdrive GT',type:'VEHICLE / TUNER',rarity:'LEGENDARY',power:94,price:10500,traits:['⚡ SPEED','◆ ARMOR'],plate:'OVER<br>DRIVE',color:'#6a9bb1'}];
const rivals=[{name:'Mara',cash:11000,emoji:'M',bg:'#ef9a85'},{name:'Rook',cash:13000,emoji:'R',bg:'#82aeb1'},{name:'Jett',cash:12500,emoji:'J',bg:'#d8b55d'}];
let bank=12800,heat=2,day=0,lotIndex=0,currentBid=4200,activeBidder='Mara',garage=[],timer,ended=false;
const $=id=>document.getElementById(id);
function money(n){return '$'+n.toLocaleString()}
function renderRivals(){ $('opponents').innerHTML=rivals.map(r=>`<div class="opponent"><div class="avatar" style="--bg:${r.bg}">${r.emoji}</div><b>${r.name}</b><span>${money(r.cash)} funds</span><strong>${r.cash>9000?'HIGH':'LOW'}</strong></div>`).join('')}
function loadLot(){const l=lots[lotIndex];$('rarity').textContent=l.rarity;$('lotNo').textContent='LOT #'+(104+lotIndex);$('itemName').textContent=l.name;$('type').textContent=l.type;$('power').textContent=l.power;$('plate').innerHTML=l.plate;$('traits').innerHTML=l.traits.map(t=>`<span>${t}</span>`).join('');$('art').style.background=`linear-gradient(145deg,${l.color} 0 48%,#f48d62 49% 72%,#2d3435 73%)`;currentBid=l.price;activeBidder=rivals[lotIndex%3].name;$('bid').textContent=money(currentBid);$('bidder').textContent=activeBidder+' is bidding';$('day').textContent=(lotIndex+1)+' / 6';startTimer()} 
function startTimer(){clearInterval(timer);let t=100;$('timerBar').style.width='100%';timer=setInterval(()=>{t-=.25;$('timerBar').style.width=t+'%';if(t<=0) finishLot()},100)}
function setLog(t){$('log').textContent=t}
function bid(){if(ended)return;clearInterval(timer);currentBid+=600;activeBidder='You';if(Math.random()<.38)heat=Math.min(5,heat+1);$('bid').textContent=money(currentBid);$('bidder').textContent='You are bidding';$('bank').textContent=money(bank);setLog('You raise the bid. '+rivals[Math.floor(Math.random()*3)].name+' is watching.');renderHeat();setTimeout(rivalMove,700)}
function rivalMove(){if(ended)return;let r=rivals.filter(x=>x.cash>currentBid+400);if(!r.length||Math.random()<.25){finishLot();return}let rival=r[Math.floor(Math.random()*r.length)];currentBid+=lotIndex%2?400:600;rival.cash-=600;activeBidder=rival.name;$('bid').textContent=money(currentBid);$('bidder').textContent=rival.name+' is bidding';renderRivals();setLog(rival.name+' counters with '+money(currentBid)+'. The room tightens.');startTimer()}
function pass(){finishLot()}
function finishLot(){clearInterval(timer);if(ended)return;let l=lots[lotIndex];let won=activeBidder==='You'&&bank>=currentBid;if(won){bank-=currentBid;garage.push(l);setLog('Sold! '+l.name+' is yours for '+money(currentBid)+'.')}else if(activeBidder==='You'){setLog('Bank too low — the lot passes you by.') }else{let r=rivals.find(x=>x.name===activeBidder);if(r){r.cash-=currentBid;r.cash=Math.max(r.cash,0)}setLog(activeBidder+' wins '+l.name+' for '+money(currentBid)+'.')}updateGarage();renderRivals();if(heat>=5){raid();return}setTimeout(nextLot,1100)}
function nextLot(){lotIndex++;if(lotIndex>=lots.length){endGame();return}loadLot()}
function updateGarage(){let total=garage.reduce((n,l)=>n+l.power*90,0);$('garage').textContent=money(total);$('garageList').innerHTML=garage.length?garage.map(l=>`<div class="garage-item"><i>◆</i><b>${l.name}</b><span>${money(l.power*90)} value</span></div>`).join(''):'<div class="empty">No properties won yet</div>';$('bank').textContent=money(bank)}
function renderHeat(){let h=$('heat');h.innerHTML=[0,1,2,3,4].map(i=>`<i class="${i>=heat?'off':''}"></i>`).join('');$('rep').textContent=heat>=4?'Wanted':heat>=2?'Doubted':'Neutral'}
function raid(){ended=true;clearInterval(timer);setTimeout(()=>{$('modal').innerHTML='<div class="modal-box"><div class="modal-mark">!</div><h2>THE RAID</h2><p>Heat level 5 shut down the auction. Your crew scatters before the lot closes.</p><button id="restart">TRY ANOTHER NIGHT</button></div>'; $('modal').classList.remove('hidden');$('restart').onclick=()=>location.reload()},300)}
function endGame(){ended=true;clearInterval(timer);let your=garage.reduce((n,l)=>n+l.power*90,0);let best=Math.max(...rivals.map(r=>r.cash));let win=your>=best;$('modal').innerHTML=`<div class="modal-box"><div class="modal-mark">${win?'★':'×'}</div><h2>${win?'YOU OWN THE NIGHT':'THE CITY OWNS YOU'}</h2><p>Your garage value: <b>${money(your)}</b></p><p>${win?'The rivals packed up. Vice Lot is yours.':'Your rivals outvalued you. Time to run it back.'}</p><button id="restart">AUCTION AGAIN</button></div>`;$('modal').classList.remove('hidden');$('restart').onclick=()=>location.reload()}
$('bidBtn').onclick=bid;$('passBtn').onclick=pass;$('infoBtn').onclick=()=>$('modal').classList.remove('hidden');$('closeModal').onclick=()=>$('modal').classList.add('hidden');$('gotIt').onclick=()=>$('modal').classList.remove('hidden')
// Fix intro button behavior
$('gotIt').onclick=()=>$('modal').classList.add('hidden');
renderRivals();renderHeat();loadLot();updateGarage();
